    const BOOT_KEY = 'ink-bamboo-boot-v1';

    function bootAllowed() {
      try {
        if (typeof window === 'undefined') return false;
        const value = new URLSearchParams(window.location.search).get('boot');
        if (value === '0') return false;
        if (value === '1') return true;
        return window.sessionStorage.getItem(BOOT_KEY) !== '1';
      } catch (error) {
        return true;
      }
    }

    function InkBoot() {
      const [visible, setVisible] = React.useState(bootAllowed);
      const [leaving, setLeaving] = React.useState(false);

      React.useEffect(() => {
        if (!visible) return undefined;

        try {
          window.sessionStorage.setItem(BOOT_KEY, '1');
        } catch (error) {
          /* the veil may replay when storage is unavailable */
        }

        let alive = true;
        let hideTimer;
        const reduced =
          typeof window.matchMedia === 'function' &&
          window.matchMedia('(prefers-reduced-motion: reduce)').matches;
        const hold = reduced ? 460 : 1750;

        const dismiss = () => {
          if (!alive) return;
          alive = false;
          setLeaving(true);
          hideTimer = window.setTimeout(() => setVisible(false), 300);
        };

        const leaveTimer = window.setTimeout(dismiss, hold);
        const onKey = (event) => {
          if (event && typeof event.preventDefault === 'function') {
            event.preventDefault();
          }
          if (event && typeof event.stopPropagation === 'function') {
            event.stopPropagation();
          }
          dismiss();
        };
        const onPointer = (event) => {
          if (event && typeof event.preventDefault === 'function') {
            event.preventDefault();
          }
          dismiss();
        };
        window.addEventListener('keydown', onKey, { once: true, capture: true });
        window.addEventListener('pointerdown', onPointer, {
          once: true,
          capture: true,
        });

        return () => {
          alive = false;
          window.clearTimeout(leaveTimer);
          window.clearTimeout(hideTimer);
          window.removeEventListener('keydown', onKey, true);
          window.removeEventListener('pointerdown', onPointer, true);
        };
      }, [visible]);

      if (!visible) return null;

      return h(
        'div',
        {
          className: 'inkb-boot' + (leaving ? ' inkb-boot--leaving' : ''),
          role: 'presentation',
          'aria-hidden': 'true',
        },
        h('span', { className: 'inkb-boot__art' }),
        h(
          'div',
          { className: 'inkb-boot__content' },
          h(
            'span',
            { className: 'inkb-boot__seal' },
            h('span', {}, '墨'),
            h('span', {}, '竹')
          ),
          h('span', { className: 'inkb-boot__title' }, '墨竹'),
          h('span', { className: 'inkb-boot__latin' }, 'INK BAMBOO · PAPER WINDOW'),
          h('span', { className: 'inkb-boot__rule' }),
          h('span', { className: 'inkb-boot__verse' }, '宁可食无肉 · 不可居无竹'),
          h('span', { className: 'inkb-boot__progress' }, h('span')),
          h(
            'span',
            { className: 'inkb-boot__hint' },
            '点击或按任意键进入',
            h('span', { className: 'inkb-boot__replay' }, '  ·  ?boot=1 重播')
          )
        )
      );
    }

    function installLiveBamboo(ctx) {
      ctx.effect(() => {
        if (typeof window === 'undefined' || typeof document === 'undefined') {
          return undefined;
        }
        if (typeof atob !== 'function' || LIVE_ART.indexOf(',') < 0) {
          return undefined;
        }

        const layer = document.createElement('div');
        layer.className = 'inkb-live';
        layer.setAttribute('aria-hidden', 'true');

        const stage = document.createElement('div');
        stage.className = 'inkb-live__stage';
        stage.innerHTML = atob(LIVE_ART.slice(LIVE_ART.indexOf(',') + 1));

        const fell = document.createElement('div');
        fell.className = 'inkb-live__fell';
        stage.appendChild(fell);
        layer.appendChild(stage);
        document.body.prepend(layer);

        const reduced =
          typeof window.matchMedia === 'function' &&
          window.matchMedia('(prefers-reduced-motion: reduce)').matches;
        const wide =
          typeof window.matchMedia === 'function'
            ? window.matchMedia('(min-width: 1181px)')
            : null;

        const timers = new Set();
        let disposed = false;
        let active = 0;

        const later = (fn, ms) => {
          const id = window.setTimeout(() => {
            timers.delete(id);
            if (!disposed) fn();
          }, ms);
          timers.add(id);
          return id;
        };

        const LEAF =
          '<svg viewBox="0 0 28 44" aria-hidden="true" focusable="false">' +
          '<path d="M3 1C9 7 21 16 24 43C16 36 7 25 3 1Z" fill="#20261A"/></svg>';

        const spawn = () => {
          if (disposed || active >= 2) return;
          if (wide && !wide.matches) return;
          if (document.visibilityState === 'hidden') return;

          const size = 12 + Math.random() * 9;
          const duration = 10 + Math.random() * 6;
          const leaf = document.createElement('span');
          leaf.className = 'inkb-fall';
          leaf.style.left = (76 + Math.random() * 19).toFixed(2) + '%';
          leaf.style.top = (6 + Math.random() * 24).toFixed(2) + '%';
          leaf.style.width = size.toFixed(1) + 'px';
          leaf.style.height = (size * 1.57).toFixed(1) + 'px';
          leaf.style.animationDuration = duration.toFixed(1) + 's';
          leaf.style.setProperty('--dx', (Math.random() * 70 - 35).toFixed(0) + 'px');
          leaf.style.setProperty('--dx2', (Math.random() * 90 - 45).toFixed(0) + 'px');
          leaf.style.setProperty('--dy', (24 + Math.random() * 20).toFixed(0) + 'vh');
          leaf.style.setProperty('--rot', (Math.random() * 520 - 260).toFixed(0) + 'deg');
          leaf.innerHTML = LEAF;

          let removed = false;
          const drop = () => {
            if (removed) return;
            removed = true;
            active -= 1;
            leaf.remove();
          };
          leaf.addEventListener('animationend', drop, { once: true });
          fell.appendChild(leaf);
          active += 1;
          later(drop, (duration + 1) * 1000);
        };

        const schedule = () => {
          if (disposed) return;
          later(() => {
            spawn();
            schedule();
          }, 7000 + Math.random() * 7000);
        };

        if (!reduced) {
          later(spawn, 3200);
          schedule();
        }

        return () => {
          disposed = true;
          for (const id of timers) window.clearTimeout(id);
          timers.clear();
          layer.remove();
        };
      }, 'ink-bamboo: live bamboo');
    }
